return $input.all().map(item => {

  const text = item.json.message?.text || item.json.message?.caption || item.json.text || '';

  const linkedinRegex = /(https?:\/\/(?:www\.)?linkedin\.com\/(?:posts|feed\/update|jobs\/view)\/[^\s]+)/i;

  const match = text.match(linkedinRegex);



  return {

    json: {

      isValid: !!match,

      url: match ? match[0] : null

    }

  };

});

