const postNodeName = 'Apify: Fetch Post Data';
const authorNodeName = 'Apify: Fetch Author Data';
const companyNodeName = 'Apify: Fetch Company Data';

const getSafeData = (nodeName) => {
    try {
        const items = $(nodeName).all();
        if (!items || items.length === 0) return {};
        const data = items[0].json;
        return Array.isArray(data) ? data[0] : data;
    } catch (e) {
        return {};
    }
};

const postData = getSafeData(postNodeName);
const authorData = getSafeData(authorNodeName);
const companyData = getSafeData(companyNodeName);

// 1. Post Details
const postInfo = {
    job_description: postData.post?.text || '',
    url: postData.post?.url || ''
};

// 2. HR Details
let hrDegree = '';
if (authorData.education?.length > 0) {
    const ed = authorData.education[0];
    hrDegree = [ed.degree, ed.fieldOfStudy].filter(Boolean).join(' - ');
}

let expYears = 0;
if (authorData.experience?.length > 0) {
    const startYears = authorData.experience.map(e => e.startDate?.year).filter(Boolean);
    if (startYears.length > 0) {
        expYears = new Date().getFullYear() - Math.min(...startYears);
    }
}

const hrInfo = {
    name: authorData.firstName ? `${authorData.firstName} ${authorData.lastName}` : (postData.author?.name || ''),
    headline: authorData.headline || postData.author?.headline || '',
    location: authorData.location?.linkedinText || '',
    degree: hrDegree,
    approx_experience_years: expYears,
    about: authorData.about || ''
};

// 3. Company Details
let compLocations = '';

if (companyData.peopleStats) {
    const locStat = companyData.peopleStats.find(s => s.statTitle === 'Locations');
    if (locStat?.values) compLocations = locStat.values.map(v => v.title).join(', ');
}

const companyInfo = {
    name: companyData.name || '',
    industry: companyData.industries?.[0]?.name || '',
    locations: compLocations,
    size: companyData.employeeCountRange ? `${companyData.employeeCountRange.start}-${companyData.employeeCountRange.end}` : '',
    website: companyData.website || '',
    description: companyData.description || ''
};

return {
  language: $('Set User Preferences').first().json.lan,
    post: postInfo,
    hr: hrInfo,
    company: companyInfo
};
